/* world-realism.js - BOARD 732, THE REALISM PASS (Marth, Nov 5 2026, verbatim: "still look robloxish"; his button: "Yes, realism pass"; and
   "breh ive asked for more realistic as cheap as possible weeks agao"). Trunks, Nov 5 2026. Every number DRAFT (unmeasured on her phone).

   WHAT IT DOES (light and colour only: no shape, no place, no save, no rnd() is touched):
     1. LINEAR LIGHT. Every colour this game paints is an sRGB number (the house never turned three's colour management on, and eight modules
        switch their own colour handling on renderer.outputEncoding, so flipping that flag would convert their colours twice). So the
        conversion happens ONCE, inside the shaders: right after a surface's colour is final (map, vertex colours and every module's own
        colour hook, all of which append to <color_fragment>), it is turned into linear light (three's own sRGBToLinear) at <alphamap_fragment>
        (or <alphatest_fragment> where a shader has no alphamap step: points), and its glow likewise at <emissivemap_fragment>. The lights then
        add up as light really does (soft terminators, shadows that hold colour), and at the end:
        (LIFT keeps a share of the painted number, so the house's dark paints, painted for gamma-space light, do not go black.)
     2. ACES FILMIC. renderer.toneMapping = THREE.ACESFilmicToneMapping, and three's ACES function returns the sRGB-encoded picture
        (the sRGB output step lives inside it: the page's output stays LinearEncoding for the reason above), with a saturation
        restore (SAT: ACES greys the bright greens). Fog mixes after it, in display colours, so the sky, the fog and the horizon stay
        the colour the sky clock paints. At night, rod vision: lit surfaces lean to moonlit blue-grey (ROD), the sky keeps its blue.
        (atmo.js's own curve and its clock exposure step aside: atmo only drives exposure under its CustomToneMapping.)
     3. THE SKY'S OWN LIGHT. One CC0 HDRI (Poly Haven "Kloofendal 43d Clear", Greg Zaal; polyhaven.com/license), baked in node
        (tools/wiring/bake-732-sky.js) to 256 x 128 with its sun clamped out (the game keeps its own sun): as a LightProbe (nine spherical
        harmonics: every lit material in the game, Lambert, Phong, Standard, gets the sky's real fill, blue above, earth-bounce below), and
        as scene.environment through three's PMREMGenerator (the Standard materials also see it in their sheen). Both follow the clock:
        the probe is tinted and scaled by the sky clock's own hemisphere light each frame (night, storm, the fight light all carry over),
        and the Standard materials' envMapIntensity with it (one shared factor through an accessor on three's MeshStandardMaterial
        prototype, set at load before any material exists: no scene walk, ever).
     4. PHYSICALLY CORRECT LIGHTS (renderer.physicallyCorrectLights): in r128 it changes the hemisphere fill (no longer x PI) and
        point/spot falloff; the game has no point lights. Set before the first compile.
   Not done here (said plainly): the sun's shadow was already the tight box round her (Itachi, board 538: 110 m, PCF soft) and is kept;
   no screen-space AO (the phone's budget: the probe's earth-bounce from below is the cheap occlusion look).

   PHONE COST: no new pass, no new material, no new program per object (the chunk edits are text in every program, made before the first
   compile); one LightProbe (r128 does not key programs on probes); one PMREM (256 cube-UV, RGBE bytes, ~1.5 MB on the GPU), made once.
   NEVER a fog type switch, never a tone-mapping switch after the first frame (each would recompile every shader).

   Use (tools/wiring/wire-realism.js does it):
     WFR_REALISM.renderer(renderer, THREE)          right after the renderer is made and graded (before anything compiles)
     WFR_REALISM.attach({ THREE, renderer, scene, sun, HEMI, night })   once the lights exist, before the first frame (night: () => 0..1)
     WFR_REALISM.tick()                              each frame, after the sky clock and the fight light set their lights
     WFR_REALISM.peek()                              what is on (the bench)
   localStorage 'wfr.realism' = 'off': nothing at all (the game as it was); 'notone': everything but the tone map (the guard's plant).   */
window.WFR_REALISM = (function () {
  'use strict';
  var C = { EXPO: 0.62, PROBE: 0.7, ENV: 0.3, SAT: 1.25, ROD: 0.5, LIFT: 0.22, PCL: true, DAY_HEMI: 0.38, DAY_SKY: [0xe4 / 255, 0xef / 255, 0xff / 255] };   // DRAFT, tuned on the four guard scenes
  var MODE = (function () { try { return localStorage.getItem('wfr.realism') || 'on'; } catch (e) { return 'on'; } })();
  try { var TUNE = JSON.parse(localStorage.getItem('wfr.realism.C') || 'null'); if (TUNE && localStorage.getItem('wfr.debug') === '1') for (var tk in TUNE) if (tk in C) C[tk] = TUNE[tk]; } catch (e) { /* the bench's tuning only (debug saves) */ }
  var ON = MODE !== 'off';
  var st = { mode: MODE, patched: false, graded: false, attached: false, envOk: false, probeOk: false, faults: [], envAcc: false, envI: 0, probeI: 0, ticks: 0 };

  /* ═══ 1 + 2: the shader text (made once, before any program compiles) ═══ */
  /* LIFT: the house's art was painted for gamma-space light, and a dark paint (a pine's 0x1f3d1f) is near black in true linear light; so the
     linear colour keeps a share of the painted number (LIFT): a softer curve in the darks (0.12 -> 0.037, not 0.013; 0.8 -> 0.65). */
  function linText() { return '\n#if !defined( WFR_LIN732 ) && !defined( WFR_LINEAR_IN732 )\n#define WFR_LIN732\n\tdiffuseColor.rgb = mix( sRGBToLinear( vec4( max( diffuseColor.rgb, 0.0 ), 1.0 ) ).rgb, max( diffuseColor.rgb, 0.0 ), ' + (+C.LIFT).toFixed(4) + ' );\n#endif\n'; }
  function linEText() { return '\n#ifndef WFR_LINEAR_IN732\n\ttotalEmissiveRadiance = mix( sRGBToLinear( vec4( max( totalEmissiveRadiance, 0.0 ), 1.0 ) ).rgb, max( totalEmissiveRadiance, 0.0 ), ' + (+C.LIFT).toFixed(4) + ' );\n#endif\n'; }
  function patch(T) {
    if (st.patched || !ON) return st.patched;
    try {
      var S = T.ShaderChunk, aces = /(vec3 ACESFilmicToneMapping\( vec3 color \) \{[\s\S]*?color \*= toneMappingExposure) \/ 0\.6;([\s\S]*?)return saturate\( color \);/;
      if (!aces.test(S.tonemapping_pars_fragment) || typeof S.lights_pars_begin !== 'string' || typeof S.tonemapping_fragment !== 'string' || typeof S.alphamap_fragment !== 'string' || typeof S.alphatest_fragment !== 'string' || typeof S.emissivemap_fragment !== 'string') { st.faults.push('chunks not as r128'); return false; }
      var LIN = linText();
      S.alphamap_fragment = LIN + S.alphamap_fragment;
      S.alphatest_fragment = LIN + S.alphatest_fragment;
      S.emissivemap_fragment = S.emissivemap_fragment + linEText();
      /* THE NIGHT rides in the uniform toneMappingExposure (1 + night amount, set by tick; the exposure itself is the baked EXPO). At night the eye
         loses colour (rod vision): LIT surfaces lean to a moonlit blue-grey by the night amount, brightness kept (the tint's luma is 1). Lit = every
         shader that includes <lights_pars_begin>; the sky, the stars and the glows (unlit) keep their colour. */
      S.lights_pars_begin = S.lights_pars_begin + '\n#define WFR_LIT732\n';
      S.tonemapping_fragment = '#if defined( TONE_MAPPING ) && defined( WFR_LIT732 )\n\tgl_FragColor.rgb = mix( gl_FragColor.rgb, vec3( dot( gl_FragColor.rgb, vec3( 0.2126, 0.7152, 0.0722 ) ) ) * vec3( 0.9, 1.0, 1.25 ), clamp( toneMappingExposure - 1.0, 0.0, 1.0 ) * ' + (+C.ROD).toFixed(4) + ' );\n#endif\n' + S.tonemapping_fragment;
      var f = function (x) { return (+x).toFixed(4); };
      S.tonemapping_pars_fragment = S.tonemapping_pars_fragment.replace(aces, function (m, a, b) {
        return a.replace(/color \*= toneMappingExposure$/, 'color *= ' + f(C.EXPO)) + ' / 0.6;' + b +
          'color = saturate( color );\n\tcolor = saturate( mix( vec3( dot( color, vec3( 0.2126, 0.7152, 0.0722 ) ) ), color, ' + f(C.SAT) + ' ) );' +
          '\n\treturn mix( pow( color, vec3( 0.41666 ) ) * 1.055 - vec3( 0.055 ), color * 12.92, vec3( lessThanEqual( color, vec3( 0.0031308 ) ) ) );';
      });
      st.patched = true;
    } catch (e) { st.faults.push('patch: ' + (e && e.message || e)); }
    return st.patched;
  }
  if (window.THREE) patch(window.THREE);

  /* the Standard materials' sheen follows the sky clock with no scene walk: envMapIntensity becomes an accessor on three's own
     MeshStandardMaterial prototype (made before any material exists), each material's own number times one shared factor, ENVG.g;
     copy() carries the material's own number (never the scaled one, so a clone never compounds). */
  var ENVG = { g: 1 }, TICKMS = [];
  function envAccessor(T) {
    if (!ON || st.envAcc || !T || !T.MeshStandardMaterial) return;
    try {
      var P = T.MeshStandardMaterial.prototype; if (Object.getOwnPropertyDescriptor(P, 'envMapIntensity')) return;
      Object.defineProperty(P, 'envMapIntensity', { configurable: true, get: function () { return (this._envI732 === undefined ? 1 : this._envI732) * ENVG.g; }, set: function (v) { this._envI732 = v; } });
      var c0 = P.copy; P.copy = function (s) { var r = c0.call(this, s); this._envI732 = s && s._envI732; return r; };
      st.envAcc = true;
    } catch (e) { st.faults.push('envAccessor: ' + (e && e.message || e)); }
  }
  if (window.THREE) envAccessor(window.THREE);

  function renderer(R, T) {
    if (!ON || !patch(T)) return false;
    try {
      R.toneMapping = MODE === 'notone' ? T.NoToneMapping : T.ACESFilmicToneMapping; R.toneMappingExposure = 1.0;
      R.physicallyCorrectLights = !!C.PCL; st.graded = true;
    } catch (e) { st.faults.push('renderer: ' + (e && e.message || e)); }
    return st.graded;
  }

  /* ═══ 3: the sky's light ═══ */
  /*SKY732-BEGIN (written by tools/wiring/bake-732-sky.js; do not edit by hand)*/
  var SKY = { src: "kloofendal_43d_clear_1k.hdr", sha256: "5077cc68a6fe4d0606099f871a8fe47162dbc48956c7d8d952f43ab40442bb11", url: "https://dl.polyhaven.org/file/ph-assets/HDRIs/hdr/1k/kloofendal_43d_clear_1k.hdr", licence: "CC0 (polyhaven.com/license), Greg Zaal / Poly Haven",
    w: 256, h: 128, clamp: 6, sunPx: 139, maxL: 71948.1,
    sh: [1.07847,1.18171,1.42291,0.12307,0.38462,0.76799,0.35389,0.39145,0.43619,0.39448,0.48216,0.57039,0.46418,0.51395,0.57994,0.27644,0.33762,0.40026,-0.01641,0.01322,0.03426,0.35999,0.41444,0.46461,0.26173,0.31207,0.36061],
    rgbe: "" };
  /*SKY732-END*/
  function rgbeBytes() { var bin = atob(SKY.rgbe), u = new Uint8Array(bin.length); for (var i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u; }
  var W = { T: null, R: null, scene: null, sun: null, HEMI: null, probe: null, base: null, env: null, tint: null, night: null, envBytes: 0 };
  function attach(o) {
    if (!ON || st.attached || !SKY) return st.attached;
    var T = o.THREE; W.T = T; W.night = typeof o.night === 'function' ? o.night : null; W.R = o.renderer; W.scene = o.scene; W.sun = o.sun; W.HEMI = o.HEMI; W.tint = new T.Color();
    try {   // the probe: nine numbers per colour, the clamped sky
      var p = new T.LightProbe(); W.base = [];
      for (var k = 0; k < 9; k++) { var v = new T.Vector3(SKY.sh[k * 3], SKY.sh[k * 3 + 1], SKY.sh[k * 3 + 2]); W.base.push(v); p.sh.coefficients[k].copy(v); }
      p.intensity = C.PROBE; p.name = 'realism732-probe'; o.scene.add(p); W.probe = p; st.probeOk = true;
    } catch (e) { st.faults.push('probe: ' + (e && e.message || e)); }
    if (C.ENV > 0) try {   // the environment: RGBE bytes, decoded by three's own PMREM (no float textures)
      var tex = new T.DataTexture(rgbeBytes(), SKY.w, SKY.h, T.RGBAFormat, T.UnsignedByteType);
      tex.encoding = T.RGBEEncoding; tex.minFilter = tex.magFilter = T.NearestFilter; tex.generateMipmaps = false; tex.flipY = true; tex.mapping = T.EquirectangularReflectionMapping; tex.needsUpdate = true;
      var pm = new T.PMREMGenerator(o.renderer), rt = pm.fromEquirectangular(tex); pm.dispose(); tex.dispose();
      W.env = rt.texture; W.envBytes = rt.width * rt.height * 4; o.scene.environment = W.env; st.envOk = true;
    } catch (e) { st.faults.push('env: ' + (e && e.message || e)); }
    st.attached = true; tick(); return true;
  }
  /* each frame: the sky clock's own fill decides how much of the sky's light there is (and its colour: the night's blue, the fight light's warm) */
  function tick() {
    if (!st.attached) return; st.ticks++; var t0 = performance.now();
    var nt = 0; try { nt = W.night ? Math.max(0, Math.min(1, +W.night() || 0)) : 0; } catch (e) { nt = 0; }
    if (W.R.toneMapping !== W.T.NoToneMapping) W.R.toneMappingExposure = 1 + nt; st.night = +nt.toFixed(3);   // the shader reads the night from it (see patch)
    var H = W.HEMI, k = Math.max(0, H.intensity / C.DAY_HEMI), c = H.color, D = C.DAY_SKY;
    W.tint.setRGB(c.r / D[0], c.g / D[1], c.b / D[2]).multiplyScalar(k);
    if (W.probe) { for (var i = 0; i < 9; i++) { var b = W.base[i], q = W.probe.sh.coefficients[i]; q.set(b.x * W.tint.r, b.y * W.tint.g, b.z * W.tint.b); } st.probeI = +(C.PROBE * (0.2126 * W.tint.r + 0.7152 * W.tint.g + 0.0722 * W.tint.b)).toFixed(3); }
    if (st.envOk) ENVG.g = st.envI = +(C.ENV * Math.min(2, 0.2126 * W.tint.r + 0.7152 * W.tint.g + 0.0722 * W.tint.b)).toFixed(3);   // every Standard material reads it (the accessor above): no scene walk
    var ms = performance.now() - t0; TICKMS.push(+ms.toFixed(4)); if (TICKMS.length > 4000) TICKMS.shift();
  }

  /* ═══ the bench's read ═══ */
  function peek(o) {
    if (o && o.resetTick) TICKMS.length = 0;
    var R = W.R; return { mode: st.mode, on: ON, patched: st.patched, graded: st.graded, attached: st.attached, envOk: st.envOk, probeOk: st.probeOk, envAcc: st.envAcc, faults: st.faults.slice(),
      tone: R ? R.toneMapping : null, night: st.night, expoU: R ? R.toneMappingExposure : null, pcl: R ? R.physicallyCorrectLights : null, enc: R ? R.outputEncoding : null, probeI: st.probeI, envI: st.envI, ticks: st.ticks,
      tickMs: TICKMS.slice(), envBytes: W.envBytes || 0,
      sky: SKY ? { src: SKY.src, w: SKY.w, h: SKY.h, clamp: SKY.clamp, licence: SKY.licence } : null, C: C };
  }
  function nightNow() { try { return W.night ? +W.night() || 0 : 0; } catch (e) { return 0; } }   /* 790 A: the city's lit windows read the page's night (0..1) */
  return { renderer: renderer, attach: attach, tick: tick, peek: peek, C: C, patch: patch, nightNow: nightNow };
})();
